import time, numpy as np
from collections import OrderedDict

def gen_ops(n, capacity, seed):
    rng = np.random.default_rng(seed)
    is_put = rng.random(n) < 0.5
    ops = np.empty((n, 3), dtype=np.int64)
    ops[:,0] = is_put
    ops[:,1] = rng.integers(0, capacity * 3, n, endpoint=True)
    ops[:,2] = np.where(is_put, rng.integers(0, 100_000, n, endpoint=True), 0)
    return ops

n=2_000_000
capacity=10_000
seed=99
ops=gen_ops(n, capacity, seed)

class MyLRU:
    __slots__=('capacity','data')
    def __init__(self, capacity):
        self.capacity=capacity
        self.data=OrderedDict()
    def get(self, key):
        try:
            val=self.data[key]
            self.data.move_to_end(key)
            return val
        except KeyError:
            return -1
    def put(self, key, val):
        if key in self.data:
            self.data.move_to_end(key)
            self.data[key]=val
        else:
            if len(self.data)>=self.capacity:
                self.data.popitem(last=False)
            self.data[key]=val

def run_ops(lru, ops):
    # returns list of get results as Python ints
    results=[]
    for is_put, key, val in ops:
        if is_put:
            lru.put(int(key), int(val))
        else:
            results.append(lru.get(int(key)))
    return results

lru=MyLRU(capacity)
start=time.perf_counter()
run_ops(lru, ops)
print('time', time.perf_counter()-start)
